#!/usr/bin/env bash
# =============================================================================
#  DevilEye — Standalone Installer (projeto embutido)
#  Uso: curl -fsSL https://raw.githubusercontent.com/darkthegod-pilot/DevilEye/claude/build-investigation-panel-3I4tI/install.sh | bash
# =============================================================================
set -eo pipefail

RED='\033[0;31m'; GREEN='\033[0;32m'; YELLOW='\033[1;33m'
CYAN='\033[0;36m'; BOLD='\033[1m'; DIM='\033[2m'; RESET='\033[0m'

ok()   { echo -e "  ${GREEN}✓${RESET} $1"; }
warn() { echo -e "  ${YELLOW}⚠${RESET}  $1"; }
err()  { echo -e "  ${RED}✗${RESET} ${RED}$1${RESET}"; }
die()  { err "$1"; exit 1; }
step() { echo -e "\n${BOLD}[${CYAN}$1${RESET}${BOLD}]${RESET} $2"; }
info() { echo -e "  ${DIM}→ $1${RESET}"; }

INSTALL_DIR="/var/www/devileye"
API_PORT=3001
NODE_MIN=18
NODE_TARGET=20
NVM_VERSION="v0.40.1"

echo ""
echo -e "${BOLD}${CYAN}╔══════════════════════════════════════════════════════╗${RESET}"
echo -e "${BOLD}${CYAN}║     DevilEye — Standalone Installer                 ║${RESET}"
echo -e "${BOLD}${CYAN}╚══════════════════════════════════════════════════════╝${RESET}"
echo ""

# ==========================================================================
# STEP 0 — Verificação do sistema
# ==========================================================================
step "0/6" "Verificando sistema..."

[[ "$EUID" -ne 0 ]] && warn "Não é root. Alguns passos podem falhar."

[[ -f /etc/os-release ]] && { . /etc/os-release; ok "OS: $NAME ${VERSION_ID:-}"; }

DISK_AVAIL=$(df -BM / | awk 'NR==2{gsub("M","",$4); print $4}')
[[ "$DISK_AVAIL" -lt 500 ]] && die "Espaço insuficiente: ${DISK_AVAIL}MB (mín 500MB)"
ok "Disco disponível: ${DISK_AVAIL}MB"

MEM_AVAIL=$(awk '/MemAvailable/{printf "%d", $2/1024}' /proc/meminfo 2>/dev/null || echo 999)
[[ "$MEM_AVAIL" -lt 256 ]] && warn "RAM baixa: ${MEM_AVAIL}MB — o build pode falhar."

curl -fsSL --max-time 5 https://registry.npmjs.org/ &>/dev/null || die "Sem acesso à internet."
ok "Conectividade: OK"

# ==========================================================================
# STEP 1 — Dependências do sistema
# ==========================================================================
step "1/6" "Verificando dependências..."

APT_NEEDED=()
for pkg in curl git openssl sqlite3; do
  command -v "$pkg" &>/dev/null || APT_NEEDED+=("$pkg")
done
if [[ ${#APT_NEEDED[@]} -gt 0 ]]; then
  info "Instalando: ${APT_NEEDED[*]}"
  DEBIAN_FRONTEND=noninteractive apt-get update -qq && apt-get install -y -qq "${APT_NEEDED[@]}"
fi

INSTALL_NODE=false
if command -v node &>/dev/null; then
  NODE_VER=$(node -e "process.stdout.write(process.versions.node.split('.')[0])")
  if [[ "$NODE_VER" -lt "$NODE_MIN" ]]; then
    warn "Node v${NODE_VER} < v${NODE_MIN}. Atualizando via nvm..."
    INSTALL_NODE=true
  else
    ok "Node.js $(node -v)"
  fi
else
  warn "Node.js não encontrado. Instalando via nvm..."
  INSTALL_NODE=true
fi

if [[ "$INSTALL_NODE" == true ]]; then
  export NVM_DIR="$HOME/.nvm"
  [[ ! -d "$NVM_DIR" ]] && curl -o- "https://raw.githubusercontent.com/nvm-sh/nvm/${NVM_VERSION}/install.sh" | bash
  set +u
  # shellcheck source=/dev/null
  source "$NVM_DIR/nvm.sh" --no-use
  nvm install "${NODE_TARGET}"
  nvm use "${NODE_TARGET}"
  nvm alias default "${NODE_TARGET}"
  set -u
  export PATH="$NVM_DIR/versions/node/$(nvm version)/bin:$PATH"
  ok "Node.js $(node -v) via nvm"
fi

command -v npm &>/dev/null || die "npm não encontrado."
ok "npm $(npm -v)"

if ! command -v pm2 &>/dev/null; then
  info "Instalando PM2..."
  npm install -g pm2 --silent --no-fund --no-audit
fi
ok "PM2 $(pm2 -v)"

command -v nginx &>/dev/null && ok "nginx $(nginx -v 2>&1 | grep -oP '[\d.]+')"                              || warn "nginx não encontrado."

# ==========================================================================
# STEP 2 — Extrair projeto
# ==========================================================================
step "2/6" "Extraindo arquivos do projeto..."

mkdir -p "$INSTALL_DIR"

# Decodifica e extrai o tarball embutido
info "Decodificando projeto embutido..."
echo "" | base64 -d | tar -xzf - -C "$INSTALL_DIR"
ok "Projeto extraído em $INSTALL_DIR"

cd "$INSTALL_DIR"

# ==========================================================================
# STEP 3 — Variáveis de ambiente
# ==========================================================================
step "3/6" "Configurando variáveis de ambiente..."

if [[ ! -f "backend/.env" ]]; then
  cp backend/.env.example backend/.env

  if command -v openssl &>/dev/null; then
    JWT_SECRET=$(openssl rand -hex 32)
  else
    JWT_SECRET=$(tr -dc 'a-zA-Z0-9' < /dev/urandom | fold -w 64 | head -n 1)
  fi

  echo ""
  if [[ -t 0 ]]; then
    read -rp "  Digite seu domínio (ex: meusite.com) [Enter = localhost]: " DOMAIN
  fi
  DOMAIN="${DOMAIN:-localhost}"

  sed -i "s|JWT_SECRET=.*|JWT_SECRET=\"${JWT_SECRET}\"|"                                   backend/.env
  sed -i "s|FRONTEND_URL=.*|FRONTEND_URL=\"https://${DOMAIN}\"|"                           backend/.env
  sed -i "s|DATABASE_URL=.*|DATABASE_URL=\"file:${INSTALL_DIR}/backend/prisma/devileye.db\"|" backend/.env
  sed -i "s|UPLOADS_DIR=.*|UPLOADS_DIR=\"${INSTALL_DIR}/backend/uploads\"|"               backend/.env

  ok "backend/.env criado"
  ok "Domínio: ${DOMAIN}"
else
  ok "backend/.env já existe"
  DOMAIN=$(grep -oP 'FRONTEND_URL=.*?//\K[^"]+' backend/.env 2>/dev/null || echo "localhost")
fi

mkdir -p backend/uploads backend/prisma
chmod 755 backend/uploads

# ==========================================================================
# STEP 4 — Dependências e banco de dados
# ==========================================================================
step "4/6" "Instalando dependências e banco de dados..."

info "npm install (backend)..."
cd "$INSTALL_DIR/backend"
npm install --omit=dev --silent --no-fund --no-audit

info "Prisma generate..."
npx prisma generate 2>/dev/null

info "Migrando banco..."
set -a; source "$INSTALL_DIR/backend/.env"; set +a
npx prisma migrate deploy 2>/dev/null || {
  warn "migrate deploy falhou — db push..."
  npx prisma db push --accept-data-loss --skip-generate
}

info "Seed..."
node prisma/seed.js && ok "Seed: OK" || warn "Seed pulado (dados já existem)"

[[ -f "${INSTALL_DIR}/backend/prisma/devileye.db" ]]   && ok "SQLite: devileye.db ($(du -sh ${INSTALL_DIR}/backend/prisma/devileye.db | cut -f1))"   || die "Banco não foi criado."

cd "$INSTALL_DIR"

# ==========================================================================
# STEP 5 — Build frontend
# ==========================================================================
step "5/6" "Build do frontend (React + Vite)..."

info "npm install (frontend)..."
npm install --silent --no-fund --no-audit

[[ -x "node_modules/.bin/vite" ]] || die "vite não encontrado em node_modules."

info "vite build..."
VITE_BASE_URL="/devileye/" npm run build

[[ -d "dist" && -n "$(ls -A dist/)" ]] || die "Build falhou: dist/ vazia."
ok "Build: dist/ ($(du -sh dist/ | cut -f1))"

cat > "${INSTALL_DIR}/nginx-devileye.conf" << NGINX
# ============================================================
# DevilEye — Nginx config
# Cole dentro do seu server{} em:
# /etc/nginx/sites-available/seu-dominio.conf
# Depois: sudo nginx -t && sudo systemctl reload nginx
# ============================================================

location /devileye/ {
    alias ${INSTALL_DIR}/dist/;
    try_files \$uri \$uri/ /devileye/index.html;
    location ~* \.(js|css|woff2?|png|jpg|svg|ico)\$ {
        expires 1y;
        add_header Cache-Control "public, immutable";
    }
}
location /api/ {
    proxy_pass         http://127.0.0.1:${API_PORT}/api/;
    proxy_http_version 1.1;
    proxy_set_header   Upgrade \$http_upgrade;
    proxy_set_header   Connection 'upgrade';
    proxy_set_header   Host \$host;
    proxy_set_header   X-Real-IP \$remote_addr;
    proxy_set_header   X-Forwarded-For \$proxy_add_x_forwarded_for;
    proxy_set_header   X-Forwarded-Proto \$scheme;
    proxy_cache_bypass \$http_upgrade;
    proxy_read_timeout 60s;
}
location /uploads/ {
    alias ${INSTALL_DIR}/backend/uploads/;
    expires 30d;
    add_header Cache-Control "public";
}
NGINX
ok "nginx-devileye.conf gerado"

# ==========================================================================
# STEP 6 — PM2
# ==========================================================================
step "6/6" "Iniciando API com PM2..."

cat > "${INSTALL_DIR}/ecosystem.config.cjs" << ECOSYSTEM
module.exports = {
  apps: [{
    name:               'devileye-api',
    script:             '${INSTALL_DIR}/backend/src/server.js',
    cwd:                '${INSTALL_DIR}/backend',
    instances:          1,
    autorestart:        true,
    watch:              false,
    max_memory_restart: '300M',
    env_file:           '${INSTALL_DIR}/backend/.env',
    env: { NODE_ENV: 'production', PORT: '${API_PORT}' }
  }]
}
ECOSYSTEM

if pm2 list 2>/dev/null | grep -q "devileye-api"; then
  pm2 reload devileye-api --update-env && ok "PM2: recarregado"
else
  pm2 start "${INSTALL_DIR}/ecosystem.config.cjs" && ok "PM2: iniciado"
fi

pm2 save --force &>/dev/null
pm2 startup 2>/dev/null | grep -E "^sudo" | bash 2>/dev/null || true

info "Aguardando API..."
sleep 3
API_OK=false
for i in 1 2 3 4 5; do
  curl -fsSL --max-time 3 "http://localhost:${API_PORT}/api/health" &>/dev/null && { API_OK=true; break; }
  sleep 1
done

[[ "$API_OK" == true ]] && ok "API: http://localhost:${API_PORT}/api/health OK"                          || warn "API ainda iniciando. Verifique: pm2 logs devileye-api"

echo ""
echo -e "${BOLD}${GREEN}╔══════════════════════════════════════════════════════╗${RESET}"
echo -e "${BOLD}${GREEN}║        DevilEye instalado com sucesso!               ║${RESET}"
echo -e "${BOLD}${GREEN}╚══════════════════════════════════════════════════════╝${RESET}"
echo ""
echo -e "  ${BOLD}API:${RESET}          http://localhost:${API_PORT}/api/health"
echo -e "  ${BOLD}Frontend:${RESET}     https://${DOMAIN}/devileye/"
echo -e "  ${BOLD}Nginx cfg:${RESET}    ${INSTALL_DIR}/nginx-devileye.conf"
echo -e "  ${BOLD}PM2 logs:${RESET}     pm2 logs devileye-api"
echo ""
echo -e "  ${BOLD}Usuários padrão:${RESET}"
echo -e "  ${DIM}carvalho / devileye123${RESET}"
echo -e "  ${DIM}ana      / devileye123${RESET}"
echo -e "  ${YELLOW}⚠  Troque as senhas em produção!${RESET}"
echo ""
